+/** An async queue of step events that a test pushes into on its own schedule. */
+function stepEventStream() {
+  const buffered: StepEvent[] = [];
+  const waiters: Array<(result: IteratorResult<StepEvent>) => void> = [];
+  let closed = false;
+
+  const push = (event: StepEvent) => {
+    const waiter = waiters.shift();
+    if (waiter !== undefined) waiter({ value: event, done: false });
+    else buffered.push(event);
+  };
+
+  const end = () => {
+    closed = true;
+    while (waiters.length > 0) waiters.shift()?.({ value: undefined, done: true });
+  };
+
+  let error: Error | undefined;
+  const fail = (err: Error) => {
+    error = err;
+    closed = true;
+    while (waiters.length > 0) waiters.shift()?.({ value: undefined, done: true });
+  };
+
+  const iterable: AsyncIterable<StepEvent> = {
+    [Symbol.asyncIterator]() {
+      return {
+        next() {
+          if (buffered.length > 0) return Promise.resolve({ value: buffered.shift()!, done: false });
+          if (error !== undefined) return Promise.reject(error);
+          if (closed) return Promise.resolve({ value: undefined, done: true });
+          return new Promise((resolve, reject) => {
+            waiters.push((result) => {
+              if (error !== undefined) reject(error);
+              else resolve(result);
+            });
+          });
+        },
+      };
+    },
+  };
+
+  return { iterable, push, end, fail };
