+import type { Rollup } from "./types.js";
+
+export class MetricsStore {
+  private readonly rollupsByMetric = new Map<string, Rollup[]>();
+
+  append(rollup: Rollup): void {
+    const existing = this.rollupsByMetric.get(rollup.metric);
+    if (existing) existing.push(rollup);
+    else this.rollupsByMetric.set(rollup.metric, [rollup]);
+  }
+
+  read(metric: string): readonly Rollup[] {
+    const existing = this.rollupsByMetric.get(metric);
+    return existing ? [...existing] : [];
+  }
+}

