new file mode 100644
index 0000000..2b1ff48
--- /dev/null
+++ b/parser.ts
@@ -0,0 +1,70 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string; position: number }
+  | { kind: "variable"; path: string; escaped: boolean; position: number }
+  | {
+      kind: "block";
+      block: "if" | "each";
+      path: string;
+      children: TemplateNode[];
+      position: number;
+    };
+
+interface OpenFrame {
+  block: "if" | "each";
+  path: string;
+  position: number;
+  children: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenFrame[] = [];
+
+  const currentChildren = (): TemplateNode[] =>
+    stack.length > 0 ? stack[stack.length - 1]!.children : root;
+
+  for (const token of tokens) {
+    if (token.kind === "text" || token.kind === "variable") {
+      currentChildren().push(token);
+      continue;
+    }
+
+    if (token.kind === "open") {
+      stack.push({
+        block: token.block,
+        path: token.path,
+        position: token.position,
+        children: [],
+      });
+      continue;
+    }
+
+    const frame = stack.pop();
+    if (!frame) {
+      throw new TemplateError(`Unexpected closing tag {{/${token.block}}}`, token.position);
+    }
+    if (frame.block !== token.block) {
+      throw new TemplateError(
+        `Mismatched closing tag {{/${token.block}}}, expected {{/${frame.block}}}`,
+        token.position,
+      );
+    }
+
+    currentChildren().push({
+      kind: "block",
+      block: frame.block,
+      path: frame.path,
+      children: frame.children,
+      position: frame.position,
+    });
+  }
+
+  if (stack.length > 0) {
+    const unclosed = stack[stack.length - 1]!;
+    throw new TemplateError(`Unclosed {{#${unclosed.block}}} block`, unclosed.position);
+  }
+
+  return root;
+}
