-    .join("");
+function escapeHtml(value: string): string {
+  return value
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
+}
+
+function resolvePath(context: unknown, path: string): unknown {
+  if (path.length === 0) return undefined;
+  let current: unknown = context;
+  for (const segment of path.split(".")) {
+    if (current === null || current === undefined || typeof current !== "object") {
+      return undefined;
+    }
+    if (!Object.prototype.hasOwnProperty.call(current, segment)) {
+      return undefined;
+    }
+    current = (current as Record<string, unknown>)[segment];
+  }
+  return current;
+}
+
+function renderNodes(nodes: readonly TemplateNode[], context: unknown): string {
+  let output = "";
+  for (const node of nodes) {
+    if (node.kind === "text") {
+      output += node.value;
+    } else if (node.kind === "variable") {
+      const value = resolvePath(context, node.path);
+      if (value === null || value === undefined) continue;
+      const text = String(value);
+      output += node.escaped ? escapeHtml(text) : text;
+    } else if (node.block === "if") {
+      if (resolvePath(context, node.path)) {
+        output += renderNodes(node.children, context);
+      }
+    } else {
+      const value = resolvePath(context, node.path);
+      if (Array.isArray(value)) {
+        for (const item of value) {
+          output += renderNodes(node.children, item);
+        }
+      }
+    }
+  }
+  return output;
+}
+
+export function render(template: string, context: TemplateContext = {}): string {
+  return renderNodes(parse(tokenize(template)), context);
 }
