+  while (cursor < template.length) {
+    const openIndex = template.indexOf("{{", cursor);
+    if (openIndex === -1) {
+      pushText(tokens, template.slice(cursor), cursor);
+      break;
+    }
+
+    if (openIndex > cursor) {
+      pushText(tokens, template.slice(cursor, openIndex), cursor);
+    }
+
+    if (template.startsWith("{{{", openIndex)) {
+      const closeIndex = template.indexOf("}}}", openIndex + 3);
+      if (closeIndex === -1) {
+        pushText(tokens, "{", openIndex);
+        cursor = openIndex + 1;
+        continue;
+      }
+      const path = template.slice(openIndex + 3, closeIndex).trim();
+      tokens.push({ kind: "variable", path, escaped: false, position: openIndex });
+      cursor = closeIndex + 3;
+      continue;
+    }
+
+    const closeIndex = template.indexOf("}}", openIndex + 2);
+    if (closeIndex === -1) {
+      pushText(tokens, template.slice(openIndex), openIndex);
+      break;
+    }
