new file mode 100644
index 0000000..614f10b
--- /dev/null
+++ b/parser.ts
@@ -0,0 +1,83 @@
+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string; position: number }
+  | { kind: "variable"; path: string; escaped: boolean; position: number }
+  | { kind: "if"; path: string; body: TemplateNode[]; position: number }
+  | { kind: "each"; path: string; body: TemplateNode[]; position: number };
+
+interface OpenFrame {
+  block: "if" | "each";
+  path: string;
+  position: number;
+  body: TemplateNode[];
+}
+
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: OpenFrame[] = [];
+
+  const currentBody = (): TemplateNode[] =>
+    stack.length > 0 ? stack[stack.length - 1]!.body : root;
+
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "text":
+        currentBody().push({
+          kind: "text",
+          value: token.value,
+          position: token.position,
+        });
+        break;
+      case "variable":
+        currentBody().push({
+          kind: "variable",
+          path: token.path,
+          escaped: token.escaped,
+          position: token.position,
+        });
+        break;
+      case "open":
+        stack.push({
+          block: token.block,
+          path: token.path,
+          position: token.position,
+          body: [],
+        });
+        break;
+      case "close": {
+        const frame = stack[stack.length - 1];
+        if (!frame) {
+          throw new TemplateError(
+            `Unexpected closing tag {{/${token.block}}}`,
+            token.position,
+          );
+        }
+        if (frame.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing tag {{/${token.block}}} for {{#${frame.block}}}`,
+            token.position,
+          );
+        }
+        stack.pop();
+        currentBody().push({
+          kind: frame.block,
+          path: frame.path,
+          body: frame.body,
+          position: frame.position,
+        });
+        break;
+      }
+    }
+  }
+
+  if (stack.length > 0) {
+    const unclosed = stack[stack.length - 1]!;
+    throw new TemplateError(
+      `Unclosed {{#${unclosed.block}}} block`,
+      unclosed.position,
+    );
+  }
+
+  return root;
+}
