+function escapeHtml(value: string): string {
+  return value
+    .replace(/&/g, "&amp;")
+    .replace(/</g, "&lt;")
+    .replace(/>/g, "&gt;")
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#39;");
+}
+
+function resolvePath(scope: unknown, path: string): unknown {
+  if (path.length === 0) {
+    return undefined;
+  }
+  if (path === ".") {
+    return scope;
+  }
+
+  let current: unknown = scope;
+  for (const segment of path.split(".")) {
+    if (
+      current === null ||
+      current === undefined ||
+      typeof current !== "object" ||
+      !Object.hasOwn(current, segment)
+    ) {
+      return undefined;
+    }
+    current = (current as Record<string, unknown>)[segment];
+  }
+  return current;
+}
+
+function renderNodes(nodes: readonly TemplateNode[], scope: unknown): string {
+  let output = "";
+
+  for (const node of nodes) {
+    switch (node.kind) {
+      case "text":
+        output += node.value;
+        break;
+      case "variable": {
+        const value = resolvePath(scope, node.path);
+        if (value !== null && value !== undefined) {
+          const text = String(value);
+          output += node.escaped ? escapeHtml(text) : text;
+        }
+        break;
+      }
+      case "if":
+        if (resolvePath(scope, node.path)) {
+          output += renderNodes(node.body, scope);
+        }
+        break;
+      case "each": {
+        const value = resolvePath(scope, node.path);
+        if (Array.isArray(value)) {
+          for (const item of value) {
+            output += renderNodes(node.body, item);
+          }
+        }
+        break;
+      }
+    }
+  }
+
+  return output;
+}
+
+export function render(template: string, context: TemplateContext = {}): string {
+  const tokens = tokenize(template);
+  const ast = parse(tokens);
+  return renderNodes(ast, context);
 }
