+        assert!(reactor.set_value(input, 4));
+        assert!(calls_diff.borrow().is_empty());
+        assert_eq!(*calls_prod.borrow(), vec![15]);
+
+        // Setting the same value does not re-trigger callbacks.
+        assert!(reactor.set_value(input, 4));
+        assert_eq!(*calls_prod.borrow(), vec![15]);
+
+        // Removing a callback stops further notifications and rejects double removal.
+        assert_eq!(reactor.remove_callback(prod, cb_prod), Ok(()));
+        assert_eq!(
+            reactor.remove_callback(prod, cb_prod),
+            Err(RemoveCallbackError::NonexistentCallback)
+        );
+        assert_eq!(
+            reactor.remove_callback(prod, cb_diff),
+            Err(RemoveCallbackError::NonexistentCallback)
+        );
+
+        assert!(reactor.set_value(input, 5));
+        assert_eq!(*calls_prod.borrow(), vec![15]);
+        assert!(calls_diff.borrow().is_empty());
     }
 }
